# Mongoles (Temujín) y eslavos (Vesna). Mismas reglas; los textos comunes vienen de camp_mal_sal.py.
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from camp_mal_sal import R, HUIR, HUIR_EN, CLAVE, CLAVE_EN, CONQ, CONQ_EN, CAMPO, CAMPO_EN, ASALTO, ASALTO_EN, AGUANTA, AGUANTA_EN, TOMAR, TOMAR_EN, HEROE, HEROE_EN, C_ASALTO, C_ASALTO_EN, C_AGUANTA, C_AGUANTA_EN, C_HUIR, C_HUIR_EN, C_HEROE, C_HEROE_EN, C_CAMPO, C_CAMPO_EN

MON = [{'id': 1, 'nombre': 'El yugo de madera', 'mapa': 'estepa', 'rivales': 1, 'batalla': 'campo', 'ejercito': {'yo': 5, 'rival': 3}, 'objetivo': {'tipo': 'escapar', 'equipo': 0, 'lado': 'oeste'}, 'dificultad': 'facil', 'limite': 15, 'guion': [{'id': 'taichiutos', 'repetible': True, 'cuando': {'cadaTurnos': 4, 'desde': 4}, 'hacer': {'refuerzos': {'tropas': ['caballero'], 'donde': 'borde', 'equipo': 1}, 'aviso': 'jinetes'}}], 'enemigos': [{'bando': 'hungria', 'reino': 'Los taichiutos'}], 'voz': 'Tu madre, Hoelun', 'historia': 'Hijo, tu padre murió envenenado y la tribu nos dejó solos en la estepa, sin nada. Ahora los taichiutos, otra tribu, te han cogido y te han puesto un yugo de madera en el cuello. Esta noche celebran una fiesta y no vigilan bien. Escapa y vuelve con nosotros.', 'meta': 'Lleva a tu héroe a una de las casillas con bandera 🚩, abajo a la izquierda: allí te esperamos. Tienes {t} turnos. Si se acaban y no ha llegado, pierdes. Y si matan a tu héroe, también.', 'contra': 'Los taichiutos', 'consejo': 'No hace falta ganar a nadie. Que tus soldados se pongan delante de tu héroe y le abran el camino.', 'avisos': {'jinetes': '¡Los taichiutos se han dado cuenta y mandan más jinetes a buscarte!'}, 'en': {'nombre': 'The wooden yoke', 'voz': 'Your mother, Hoelun', 'historia': "Son, your father was poisoned and the tribe left us alone on the steppe, with nothing. Now the Taichiut, another tribe, have caught you and put a wooden yoke around your neck. Tonight they are having a feast and aren't watching carefully. Escape and come back to us.", 'meta': "Take your hero to one of the hexes with a flag 🚩, at the bottom left: we are waiting for you there. You have {t} turns. If they run out and your hero hasn't got there, you lose. And if your hero is killed, you lose too.", 'contra': 'The Taichiut', 'consejo': "You don't need to beat anyone. Put your soldiers in front of your hero and let them clear the way.", 'avisos': {'jinetes': 'The Taichiut have noticed and are sending more riders to find you!'}}}, {'id': 2, 'nombre': 'Los ocho caballos', 'mapa': 'gobi', 'rivales': 1, 'batalla': 'campo', 'ejercito': {'yo': 6, 'rival': 5}, 'equipos': None, 'dificultad': 'normal', 'limite': 12, 'enemigos': [{'bando': 'hungria', 'reino': 'Los ladrones de la estepa'}], 'voz': "Bo'orchu, un chico de otra tribu", 'historia': 'No te conozco de nada, pero me has caído bien. Unos ladrones se han llevado los ocho caballos de tu familia, ¿verdad? Toma mi caballo, que está fresco, y vamos juntos a por ellos. Desde hoy, lo que sea tuyo es mío, y lo mío, tuyo.', 'meta': 'Aquí no hay pueblos: solo tu ejército contra el suyo. Derrota a todos sus soldados. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Los ladrones de la estepa', 'consejo': "Bo'orchu va contigo. Ataca a cada ladrón con dos o tres soldados a la vez.", 'en': {'nombre': 'The eight horses', 'voz': "Bo'orchu, a boy from another tribe", 'historia': "I don't know you at all, but I like you. Some thieves have taken your family's eight horses, haven't they? Take my horse, it's fresh, and let's go after them together. From today, what's yours is mine, and what's mine is yours.", 'meta': 'There are no villages here: only your army against theirs. Defeat all their soldiers. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': 'The steppe thieves', 'consejo': "Bo'orchu is with you. Attack each thief with two or three soldiers at once."}}, {'id': 3, 'nombre': 'Börte', 'mapa': 'torres', 'rivales': 3, 'equipos': [0, 0, 1, 1], 'objetivo': {'tipo': 'tomar', 'jugador': 2}, 'dificultad': 'normal', 'limite': 26, 'enemigos': [{'bando': 'hungria', 'reino': 'Yamuja, tu hermano de sangre'}, {'bando': 'hungria', 'reino': 'Los merkitas'}, {'bando': 'hungria', 'reino': 'Los guerreros merkitas'}], 'voz': 'Yamuja, tu hermano de sangre', 'historia': 'Hermano, me he enterado. Los merkitas, una tribu enemiga, entraron de noche en tu campamento y se llevaron a Börte, tu mujer. No vas a ir solo: cuando éramos niños juramos ser hermanos, y un hermano no se queda mirando. Mis jinetes vienen contigo.', 'meta': 'Conquista el campamento de los merkitas, su pueblo principal, y rescata a Börte. Tienes {t} turnos. Si se acaban y no lo has conquistado, pierdes.', 'contra': 'Los merkitas y sus guerreros, que van juntos. Yamuja pelea contigo', 'consejo': 'Yamuja es tu aliado: no hace falta que lo hagas todo solo. Id juntos a por el campamento.', 'en': {'nombre': 'Börte', 'voz': 'Jamukha, your blood brother', 'historia': "Brother, I've heard. The Merkits, an enemy tribe, came into your camp at night and took Börte, your wife. You're not going alone: when we were boys we swore to be brothers, and a brother doesn't just stand and watch. My riders are coming with you.", 'meta': "Conquer the Merkit camp, their main village, and rescue Börte. You have {t} turns. If they run out and you haven't conquered it, you lose.", 'contra': 'The Merkits and their warriors, who fight together. Jamukha fights with you', 'consejo': "Jamukha is your ally: you don't have to do everything alone. Go for the camp together.", 'avisos': {'yamuja1': "Jamukha's riders bring you two catapults near the Merkit camp. They are for breaking walls.", 'yamuja2': 'More help arrives near the camp: two knights and another catapult.'}}, 'guion': [{'id': 'regalo_yamuja', 'cuando': {'turno': 4}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['lancero', 'espadachin', 'catapulta', 'catapulta'], 'donde': 'objetivo'}, 'aviso': 'yamuja1'}}, {'id': 'regalo_yamuja2', 'cuando': {'turno': 9}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['caballero', 'caballero', 'catapulta'], 'donde': 'objetivo'}, 'aviso': 'yamuja2'}}], 'avisos': {'yamuja1': 'Los jinetes de Yamuja te traen dos catapultas cerca del campamento merkita. Sirven para romper murallas.', 'yamuja2': 'Llega más ayuda cerca del campamento: dos caballeros y otra catapulta.'}}, {'id': 4, 'nombre': 'Los pastos del río', 'mapa': 'estepa', 'rivales': 2, 'batalla': 'clave', 'objetivo': {'tipo': 'clave', 'n': 2, 'turnos': 2}, 'dificultad': 'normal', 'limite': 12, 'enemigos': [{'bando': 'hungria', 'reino': 'Los de Yamuja'}, {'bando': 'hungria', 'reino': 'Los clanes que dudan'}], 'voz': 'Börte, tu mujer', 'historia': 'Ya estoy en casa, gracias a ti y a Yamuja. Pero ¿no lo ves? Los clanes de la tribu empiezan a elegir: unos te siguen a ti y otros a él. Yamuja quiere a los ricos; tú, a los que valen. Quien tenga los mejores pastos se quedará con la tribu.', 'meta': 'En el mapa hay casillas marcadas con una estrella: son los mejores pastos. Pisa dos de ellas con tus soldados y consigue que sigan siendo tuyas durante dos turnos seguidos. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Los de Yamuja y los clanes que dudan. Cada uno va por su cuenta', 'consejo': 'Llega rápido a los pastos y deja un soldado encima de cada uno.', 'en': {'nombre': 'The river pastures', 'voz': 'Börte, your wife', 'historia': "I'm home now, thanks to you and Jamukha. But can't you see? The clans of the tribe are starting to choose: some follow you and some follow him. Jamukha wants the rich; you want the ones who are worth something. Whoever holds the best pastures will keep the tribe.", 'meta': 'There are hexes on the map marked with a star: they are the best pastures. Step on two of them with your soldiers and keep them yours for two turns in a row. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': "Jamukha's people and the clans who can't decide. Each fights for himself", 'consejo': 'Get to the pastures quickly and leave a soldier on top of each one.'}}, {'id': 5, 'nombre': 'Los tártaros', 'mapa': 'gobi', 'rivales': 2, 'equipos': [0, 1, 1], 'dificultad': 'normal', 'limite': 18, 'guion': [{'id': 'china', 'cuando': {'turno': 7}, 'hacer': {'refuerzos': {'tropas': ['caballero', 'arquero'], 'donde': 'capital', 'jugador': 0}, 'oro': {'jugador': 0, 'cantidad': 40}, 'aviso': 'china'}}, {'id': 'clanes', 'cuando': {'turno': 11}, 'hacer': {'refuerzos': {'tropas': ['lancero', 'caballero', 'caballero'], 'donde': 'capital', 'jugador': 0}, 'aviso': 'clanes'}}], 'enemigos': [{'bando': 'hungria', 'reino': 'Los tártaros'}, {'bando': 'hungria', 'reino': 'Los tártaros del desierto'}], 'voz': 'Börte, tu mujer', 'historia': 'Los tártaros, los que envenenaron a tu padre, han atacado la frontera del imperio de China. Su emperador pagará a quien los castigue. Es la ocasión de vengar a tu padre, y encima te pagan por ello. Cruzaremos el desierto.', 'meta': 'Acaba con los tártaros: quítales sus pueblos y derrota a todos sus soldados. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Dos grupos de tártaros, que van juntos', 'consejo': 'Van juntos: no dejes tus pueblos vacíos. Aguanta los primeros turnos: puede que llegue ayuda.', 'avisos': {'china': 'El emperador de China te manda 40 monedas de oro y dos soldados: un caballero y un arquero.', 'clanes': 'Más clanes se unen a ti al ver que ganas: un lancero y dos caballeros.'}, 'en': {'nombre': 'The Tatars', 'voz': 'Börte, your wife', 'historia': "The Tatars, the ones who poisoned your father, have attacked the border of the empire of China. Its emperor will pay whoever punishes them. It's the chance to avenge your father, and they'll pay you for it too. We'll cross the desert.", 'meta': 'Beat the Tatars: take their villages and defeat all their soldiers. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': 'Two groups of Tatars, who fight together', 'consejo': "They fight together: don't leave your villages empty. Hold on for the first turns: help may come.", 'avisos': {'china': 'The emperor of China sends you 40 gold coins and two soldiers: a knight and an archer.', 'clanes': 'More clans join you when they see you winning: a spearman and two knights.'}}}, {'id': 6, 'nombre': 'Los trece campamentos', 'mapa': 'sierra', 'rivales': 2, 'equipos': [0, 1, 1], 'objetivo': {'tipo': 'aguantar', 'equipo': 0, 'turnos': 14, 'capital': True}, 'dificultad': 'dificil', 'limite': 14, 'hucha': 1, 'guion': [{'id': 'yamuja_ataca', 'repetible': True, 'cuando': {'cadaTurnos': 2, 'desde': 3}, 'hacer': {'refuerzos': {'tropas': ['lancero', 'espadachin', 'catapulta'], 'donde': 'borde', 'equipo': 1}, 'aviso': 'yamuja'}}], 'enemigos': [{'bando': 'hungria', 'reino': 'Los de Yamuja'}, {'bando': 'hungria', 'reino': 'Los trece campamentos'}], 'voz': 'Börte, tu mujer', 'historia': 'Yamuja te ha atacado por sorpresa con trece campamentos de guerreros, y has perdido. Ya no es tu hermano: ahora es tu rival. Nos quedan la mitad de los hombres y la mitad del oro. Nos hemos refugiado en las montañas. Aquí hay que aguantar.', 'meta': 'Defiende tu pueblo principal (el de la estrella) durante {t} turnos. Si te lo quitan, pierdes. Si al acabar el turno {t} sigue siendo tuyo, ganas.', 'contra': 'Los de Yamuja y los trece campamentos, que van juntos', 'consejo': 'Empiezas con la mitad del oro de siempre. Gástalo en llenar tu pueblo principal de soldados.', 'avisos': {'yamuja': '¡Llegan más guerreros de Yamuja, con una catapulta para romper tus murallas!'}, 'en': {'nombre': 'The thirteen camps', 'voz': 'Börte, your wife', 'historia': "Jamukha has attacked you by surprise with thirteen camps of warriors, and you have lost. He is no longer your brother: now he is your rival. We have half our men and half our gold left. We've taken shelter in the mountains. Here we have to hold out.", 'meta': "Defend your main village (the one with the star) for {t} turns. If they take it, you lose. If it's still yours at the end of turn {t}, you win.", 'contra': "Jamukha's people and the thirteen camps, who fight together", 'consejo': 'You start with half your usual gold. Spend it on filling your main village with soldiers.', 'avisos': {'yamuja': "More of Jamukha's warriors are coming, with a catapult to break your walls!"}}}, {'id': 7, 'nombre': 'La trampa de Togril', 'mapa': 'torres', 'rivales': 3, 'objetivo': {'tipo': 'escapar', 'equipo': 0, 'lado': 'sur'}, 'dificultad': 'dificil', 'limite': 16, 'guion': [{'id': 'keraitas', 'repetible': True, 'cuando': {'cadaTurnos': 3, 'desde': 3}, 'hacer': {'refuerzos': {'tropas': ['caballero', 'caballero'], 'donde': 'borde', 'equipo': 1}, 'aviso': 'keraitas'}}], 'enemigos': [{'bando': 'polonia', 'reino': 'Los keraítas'}, {'bando': 'polonia', 'reino': 'Los guerreros de Togril'}, {'bando': 'hungria', 'reino': 'Los de Yamuja'}], 'voz': "Bo'orchu, tu amigo", 'historia': '¡Es una trampa, Temujín! Togril, el jefe de los keraítas, que era como un padre para ti, te invitó a una boda. Pero Yamuja lo ha convencido de que eres un peligro. Sus campamentos nos rodean. Hay que salir de aquí antes de que nos cierren el paso.', 'meta': 'Lleva a tu héroe hasta el borde de abajo del mapa: a una de las casillas con bandera 🚩. Tienes {t} turnos. Si se acaban y no ha llegado, pierdes. Y si matan a tu héroe, también.', 'contra': 'Los keraítas, los guerreros de Togril y los de Yamuja. Cada uno va por su cuenta', 'consejo': 'No hace falta ganar a nadie. Que tus soldados se pongan delante de tu héroe y le abran el camino.', 'avisos': {'keraitas': '¡Llegan dos jinetes keraítas más a cortarte el paso!'}, 'en': {'nombre': "Toghrul's trap", 'voz': "Bo'orchu, your friend", 'historia': "It's a trap, Temujin! Toghrul, chief of the Keraites, who was like a father to you, invited you to a wedding. But Jamukha has convinced him that you are dangerous. Their camps surround us. We have to get out of here before they block the way.", 'meta': "Take your hero to the bottom edge of the map: to one of the hexes with a flag 🚩. You have {t} turns. If they run out and your hero hasn't got there, you lose. And if your hero is killed, you lose too.", 'contra': "The Keraites, Toghrul's warriors and Jamukha's people. Each fights for himself", 'consejo': "You don't need to beat anyone. Put your soldiers in front of your hero and let them clear the way.", 'avisos': {'keraitas': 'Two more Keraite riders arrive to block your way!'}}}, {'id': 8, 'nombre': 'El agua de barro', 'mapa': 'estepa', 'rivales': 2, 'batalla': 'campo', 'ejercito': {'yo': 15, 'rival': 6}, 'equipos': [0, 1, 1], 'objetivo': {'tipo': 'heroe'}, 'dificultad': 'dificil', 'limite': 12, 'enemigos': [{'bando': 'polonia', 'reino': 'Togril, el jefe keraíta'}, {'bando': 'polonia', 'reino': 'Los keraítas'}], 'voz': "Bo'orchu, tu amigo", 'historia': 'Solo te quedan unos pocos hombres. Habéis bebido juntos agua de barro, jurando no separaros nunca. Son pocos, pero valen por cien. Togril cree que estás acabado y lo está celebrando. Esta noche no nos esperan.', 'meta': 'Aquí no hay pueblos: solo los ejércitos. Mata a los héroes de Togril y de sus keraítas y que tu héroe siga vivo. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Togril y los keraítas, que van juntos', 'consejo': 'Cuida a tu héroe: si lo matan, pierdes. Ataca a sus héroes con varios soldados a la vez.', 'en': {'nombre': 'Muddy water', 'voz': "Bo'orchu, your friend", 'historia': "You have only a few men left. You drank muddy water together, swearing never to be parted. They are few, but each is worth a hundred. Toghrul thinks you're finished and is celebrating. Tonight they won't be expecting us.", 'meta': 'There are no villages here: only the armies. Kill the heroes of Toghrul and his Keraites and keep your hero alive. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': 'Toghrul and the Keraites, who fight together', 'consejo': 'Look after your hero: if yours is killed, you lose. Attack their heroes with several soldiers at once.'}}, {'id': 9, 'nombre': 'Las hogueras', 'mapa': 'costa', 'rivales': 3, 'batalla': 'campo', 'ejercito': {'yo': 18, 'rival': 4}, 'equipos': [0, 1, 1, 1], 'dificultad': 'dificil', 'limite': 15, 'enemigos': [{'bando': 'sacro_imperio', 'reino': 'Los naimanos'}, {'bando': 'sacro_imperio', 'reino': 'Los jinetes naimanos'}, {'bando': 'hungria', 'reino': 'Los de Yamuja'}], 'voz': "Bo'orchu, tu amigo", 'historia': 'El último gran pueblo de la estepa, los naimanos, se ha unido a Yamuja. Son muchos. Esta noche cada soldado ha encendido cinco hogueras, y al verlas han creído que somos muchísimos. Ahora tienen miedo. Es el momento de atacar.', 'meta': 'Aquí no hay pueblos: solo tu ejército contra el suyo. Derrota a todos sus soldados. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Los naimanos, sus jinetes y los de Yamuja, que van juntos', 'consejo': 'Mantén juntos a tus soldados y ataca a cada enemigo con varios a la vez.', 'en': {'nombre': 'The campfires', 'voz': "Bo'orchu, your friend", 'historia': "The last great people of the steppe, the Naimans, have joined Jamukha. There are a lot of them. Tonight every soldier lit five campfires, and when they saw them they thought we were a huge army. Now they're afraid. This is the moment to attack.", 'meta': 'There are no villages here: only your army against theirs. Defeat all their soldiers. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': "The Naimans, their riders and Jamukha's people, who fight together", 'consejo': 'Keep your soldiers together and attack each enemy with several at once.', 'avisos': {'naimanos': "More Naiman riders arrive! They don't believe the campfires any more."}}, 'guion': [{'id': 'mas_naimanos', 'cuando': {'turno': 8}, 'hacer': {'refuerzos': {'equipo': 1, 'tropas': ['caballero', 'caballero'], 'donde': 'borde'}, 'aviso': 'naimanos'}}], 'avisos': {'naimanos': '¡Llegan más jinetes naimanos! Ya no se creen lo de las hogueras.'}}, {'id': 10, 'nombre': 'Chakirmaut', 'mapa': 'torres', 'rivales': 2, 'batalla': 'asalto', 'ejercito': 18, 'equipos': [0, 1, 1], 'dificultad': 'dificil', 'limite': 31, 'guion': [{'id': 'clanes_final', 'cuando': {'turno': 6}, 'hacer': {'refuerzos': {'tropas': ['espadachin', 'arquero', 'lancero', 'caballero'], 'donde': 'borde', 'jugador': 0}, 'aviso': 'clanes'}}, {'id': 'maquinas_final', 'cuando': {'turno': 9}, 'hacer': {'refuerzos': {'tropas': ['caballero', 'catapulta', 'catapulta'], 'donde': 'borde', 'jugador': 0}, 'aviso': 'maquinas'}}], 'enemigos': [{'bando': 'hungria'}, {'bando': 'sacro_imperio', 'reino': 'Los naimanos'}], 'voz': 'Yamuja', 'historia': '«Temujín, hermano. Cuando éramos niños jugábamos en el río helado y te regalé una punta de flecha de hueso.» Yamuja habla desde la montaña, con los naimanos detrás. «Ahora uno de los dos tiene que quedarse con la estepa entera. Ven a buscarme.»', 'meta': 'Aquí no tienes pueblo: solo tu ejército. Conquista el pueblo principal de Yamuja. Tienes {t} turnos. Si se acaban y no lo has conquistado, pierdes.', 'contra': 'Yamuja y los naimanos, que van juntos', 'consejo': 'Es la última batalla. Yamuja es muy fuerte: no le ataques con un soldado solo.', 'avisos': {'clanes': 'Llegan los clanes que te siguen: un espadachín, un arquero, un lancero y un caballero.', 'maquinas': 'Llega un caballero con dos catapultas para romper la muralla de Yamuja.'}, 'en': {'nombre': 'Chakirmaut', 'voz': 'Jamukha', 'historia': '«Temujin, brother. When we were boys we played on the frozen river and I gave you a bone arrowhead.» Jamukha speaks from the mountain, with the Naimans behind him. «Now one of us has to keep the whole steppe. Come and find me.»', 'meta': "You have no village here: only your army. Conquer Jamukha's main village. You have {t} turns. If they run out and you haven't conquered it, you lose.", 'contra': 'Jamukha and the Naimans, who fight together', 'consejo': "This is the last battle. Jamukha is very strong: don't attack him with just one soldier.", 'avisos': {'clanes': 'The clans who follow you arrive: a swordsman, an archer, a spearman and a knight.', 'maquinas': "A knight arrives with two catapults to break Jamukha's wall."}}}]
ESL = [{'id': 1, 'nombre': 'La aldea en llamas', 'mapa': 'bosque_viejo', 'rivales': 1, 'batalla': 'campo', 'ejercito': {'yo': 6, 'rival': 5}, 'dificultad': 'facil', 'limite': 12, 'enemigos': [{'bando': 'avaros', 'reino': 'Los jinetes ávaros'}], 'voz': 'La abuela Mokosha', 'historia': 'Vesna, niña, los ávaros, unos jinetes que vienen de la llanura, han quemado la aldea. Tú tienes un don: las tormentas te escuchan. Todavía quedan algunos jinetes por aquí. Échalos, y luego llevaremos a la gente que queda al bosque viejo, por sendas que ellos no conocen.', 'meta': 'Aquí no hay pueblos: solo tu ejército contra el suyo. Derrota a todos sus soldados. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Los jinetes ávaros', 'consejo': 'Ataca a cada jinete con dos o tres soldados a la vez: así caen antes.', 'en': {'nombre': 'The burning village', 'voz': 'Grandmother Mokosha', 'historia': "Vesna, child, the Avars, riders who come from the plain, have burnt the village. You have a gift: storms listen to you. There are still some riders around here. Drive them away, and then we'll take the people who are left into the old forest, along paths they don't know.", 'meta': 'There are no villages here: only your army against theirs. Defeat all their soldiers. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': 'The Avar riders', 'consejo': 'Attack each rider with two or three soldiers at once: they fall faster.'}}, {'id': 2, 'nombre': 'El tributo del río', 'mapa': 'costa', 'rivales': 1, 'batalla': 'clave', 'objetivo': {'tipo': 'clave', 'n': 3, 'turnos': 2}, 'dificultad': 'normal', 'limite': 12, 'enemigos': [{'bando': 'avaros', 'reino': 'Los cobradores del kagan'}], 'voz': 'Radim, el herrero', 'historia': 'Los ávaros cobran por cruzar el río: grano, pieles y chicos para su ejército. Eso es un tributo, y lo manda cobrar el kagan, su jefe. Yo forjo las lanzas y tú haces caer los rayos. Si les quitamos los vados del río, se acabó el tributo.', 'meta': 'En el mapa hay casillas marcadas con una estrella: son los vados, los sitios por donde se cruza el río. Pisa tres de ellas con tus soldados y consigue que sigan siendo tuyas durante dos turnos seguidos. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Los cobradores del kagan', 'consejo': 'Necesitas tres vados a la vez. Deja un soldado fuerte encima de cada uno.', 'en': {'nombre': 'The river tribute', 'voz': 'Radim, the blacksmith', 'historia': "The Avars make people pay to cross the river: grain, furs and boys for their army. That's a tribute, and it's collected on the orders of the khagan, their chief. I forge the spears and you bring down the lightning. If we take the river fords, the tribute is over.", 'meta': 'There are hexes on the map marked with a star: they are the fords, the places where you can cross the river. Step on three of them with your soldiers and keep them yours for two turns in a row. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': "The khagan's collectors", 'consejo': 'You need three fords at the same time. Leave a strong soldier on top of each one.'}}, {'id': 3, 'nombre': 'La tribu del lago', 'mapa': 'isla', 'rivales': 1, 'batalla': 'campo', 'ejercito': {'yo': 7, 'rival': 7}, 'objetivo': {'tipo': 'heroe'}, 'dificultad': 'normal', 'limite': 12, 'enemigos': [{'bando': 'eslavos', 'reino': 'La tribu del lago'}], 'voz': 'Radim, el herrero', 'historia': 'La tribu del lago no quiere unirse a nosotros. Su jefe, Borislav, dice que una muchacha no manda a nadie. Ha propuesto una pelea: si vences a su campeón, el mejor guerrero de la tribu, todos te seguirán. Demuéstrale que se equivoca.', 'meta': 'Aquí no hay pueblos: solo los ejércitos. Vence al campeón de Borislav (su héroe) y que tu héroe siga vivo. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'El campeón de Borislav y la tribu del lago', 'consejo': 'Cuida a tu héroe: si cae, pierdes. Ataca a su campeón con varios soldados a la vez.', 'en': {'nombre': 'The lake tribe', 'voz': 'Radim, the blacksmith', 'historia': "The lake tribe doesn't want to join us. Their chief, Borislav, says a girl can't lead anyone. He has proposed a fight: if you beat his champion, the best warrior of the tribe, they will all follow you. Show him he's wrong.", 'meta': "There are no villages here: only the armies. Beat Borislav's champion (their hero) and keep your hero alive. You have {t} turns. If they run out first, whoever has more points wins.", 'contra': "Borislav's champion and the lake tribe", 'consejo': 'Look after your hero: if yours falls, you lose. Attack their champion with several soldiers at once.'}}, {'id': 4, 'nombre': 'Las colinas del trueno', 'mapa': 'torres', 'rivales': 3, 'equipos': [0, 0, 1, 1], 'objetivo': {'tipo': 'tomar', 'jugador': 2}, 'dificultad': 'normal', 'limite': 26, 'enemigos': [{'bando': 'eslavos', 'reino': 'Borislav, tu aliado'}, {'bando': 'avaros', 'reino': 'Los vigías ávaros'}, {'bando': 'avaros', 'reino': 'Los jinetes del kagan'}], 'voz': 'Borislav, el jefe del lago', 'historia': 'Me ganaste limpio, hechicera, y mi palabra se cumple: mis hombres pelearán a tu lado. Desde las colinas del trueno, los vigías ávaros ven todos los caminos. Si tomamos su torre, sabremos por dónde vienen antes de que lleguen.', 'meta': 'Conquista la torre de los vigías ávaros, que es su pueblo principal. Tienes {t} turnos. Si se acaban y no lo has conquistado, pierdes.', 'contra': 'Los vigías ávaros y los jinetes del kagan, que van juntos. Borislav pelea contigo', 'consejo': 'Borislav es tu aliado: id juntos a por la torre.', 'en': {'nombre': 'The thunder hills', 'voz': 'Borislav, chief of the lake', 'historia': "You beat me fairly, witch, and I keep my word: my men will fight at your side. From the thunder hills, the Avar lookouts can see every road. If we take their tower, we'll know which way they're coming before they get here.", 'meta': "Conquer the tower of the Avar lookouts, which is their main village. You have {t} turns. If they run out and you haven't conquered it, you lose.", 'contra': "The Avar lookouts and the khagan's riders, who fight together. Borislav fights with you", 'consejo': 'Borislav is your ally: go for the tower together.', 'avisos': {'radim1': "Radim brings you two catapults near the lookouts' tower. They are for breaking walls.", 'radim2': 'More help arrives near the tower: a knight and another catapult.'}}, 'guion': [{'id': 'radim1', 'cuando': {'turno': 4}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['lancero', 'espadachin', 'catapulta', 'catapulta'], 'donde': 'objetivo'}, 'aviso': 'radim1'}}, {'id': 'radim2', 'cuando': {'turno': 9}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['caballero', 'catapulta'], 'donde': 'objetivo'}, 'aviso': 'radim2'}}], 'avisos': {'radim1': 'Radim te trae dos catapultas cerca de la torre de los vigías. Sirven para romper murallas.', 'radim2': 'Llega más ayuda cerca de la torre: un caballero y otra catapulta.'}}, {'id': 5, 'nombre': 'El invierno largo', 'mapa': 'bosque_viejo', 'rivales': 2, 'equipos': [0, 1, 1], 'objetivo': {'tipo': 'aguantar', 'equipo': 0, 'turnos': 14, 'capital': True}, 'dificultad': 'normal', 'limite': 14, 'hucha': 1, 'guion': [{'id': 'avaros_invierno', 'repetible': True, 'cuando': {'cadaTurnos': 2, 'desde': 4}, 'hacer': {'refuerzos': {'tropas': ['lancero', 'espadachin', 'catapulta'], 'donde': 'borde', 'equipo': 1}, 'aviso': 'avaros'}}], 'enemigos': [{'bando': 'avaros', 'reino': 'Los jinetes ávaros'}, {'bando': 'avaros', 'reino': 'Los jinetes del kagan'}], 'voz': 'La abuela Mokosha', 'historia': 'No recuerdo un invierno tan duro. Los graneros están casi vacíos y los ávaros lo saben: vienen ahora que estamos débiles. Pero el bosque y el frío también están de nuestro lado. Hay que aguantar hasta la primavera.', 'meta': 'Defiende tu pueblo principal (el de la estrella) durante {t} turnos, hasta que llegue la primavera. Si te lo quitan, pierdes. Si al acabar el turno {t} sigue siendo tuyo, ganas.', 'contra': 'Los jinetes ávaros y los del kagan, que van juntos', 'consejo': 'Empiezas con la mitad del oro de siempre. Gástalo en llenar tu pueblo principal de soldados.', 'avisos': {'avaros': '¡Llegan más ávaros, con una catapulta para romper tus murallas!'}, 'en': {'nombre': 'The long winter', 'voz': 'Grandmother Mokosha', 'historia': "I don't remember a winter this hard. The granaries are almost empty and the Avars know it: they're coming now that we're weak. But the forest and the cold are on our side too. We have to hold out until spring.", 'meta': "Defend your main village (the one with the star) for {t} turns, until spring comes. If they take it, you lose. If it's still yours at the end of turn {t}, you win.", 'contra': "The Avar riders and the khagan's riders, who fight together", 'consejo': 'You start with half your usual gold. Spend it on filling your main village with soldiers.', 'avisos': {'avaros': 'More Avars are coming, with a catapult to break your walls!'}}}, {'id': 6, 'nombre': 'Los tratantes de la costa', 'mapa': 'torres', 'rivales': 2, 'batalla': 'asalto', 'ejercito': 12, 'dificultad': 'dificil', 'limite': 30, 'guion': [{'id': 'maquinas_costa', 'cuando': {'turno': 3}, 'hacer': {'refuerzos': {'tropas': ['catapulta', 'catapulta', 'catapulta'], 'donde': 'borde', 'jugador': 0}, 'aviso': 'catapultas'}}, {'id': 'maquinas_costa2', 'cuando': {'turno': 8}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['espadachin', 'caballero', 'catapulta'], 'donde': 'borde'}, 'aviso': 'refuerzo2'}}], 'enemigos': [{'bando': 'sacro_imperio', 'reino': 'Los tratantes del oeste'}, {'bando': 'avaros', 'reino': 'La escolta ávara'}], 'voz': 'Radim, el herrero', 'historia': '¿Sabes adónde se llevan a los que capturan los ávaros? Los venden a unos tratantes, gente que compra y vende personas, que vienen del oeste por la costa. Mi hermano está entre ellos, encerrado en su puerto. Si lo tomamos, volverá a casa, y con él muchos otros.', 'meta': 'Aquí no tienes pueblo: solo tu ejército. Conquista el puerto de los tratantes, que es su pueblo principal. Tienes {t} turnos. Si se acaban y no lo has conquistado, pierdes.', 'contra': 'Los tratantes del oeste y su escolta ávara. Cada uno va por su cuenta', 'consejo': 'Aquí no puedes reclutar soldados, así que cuídalos. Sin catapultas cuesta mucho romper una muralla.', 'avisos': {'catapultas': 'Radim ha construido tres catapultas y te las trae. Sirven para romper murallas.', 'refuerzo2': 'Llegan más hombres de la aldea: un espadachín, un caballero y otra catapulta.'}, 'en': {'nombre': 'The traders of the coast', 'voz': 'Radim, the blacksmith', 'historia': "Do you know where the people the Avars capture are taken? They sell them to traders, people who buy and sell other people, who come from the west along the coast. My brother is among them, locked up in their port. If we take it, he'll come home, and many others with him.", 'meta': "You have no village here: only your army. Conquer the traders' port, which is their main village. You have {t} turns. If they run out and you haven't conquered it, you lose.", 'contra': 'The traders from the west and their Avar escort. Each fights for himself', 'consejo': "You can't recruit soldiers here, so look after them. Without catapults it's very hard to break a wall.", 'avisos': {'catapultas': 'Radim has built three catapults and brings them to you. They are for breaking walls.', 'refuerzo2': 'More men arrive from the village: a swordsman, a knight and another catapult.'}}}, {'id': 7, 'nombre': 'Las siete tribus', 'mapa': 'torres', 'rivales': 3, 'equipos': [0, 1, 1, 1], 'dificultad': 'dificil', 'limite': 18, 'guion': [{'id': 'tribu_se_une', 'cuando': {'turno': 9}, 'hacer': {'equipo': {'jugador': 2, 'nuevo': 0}, 'aviso': 'tribu'}}], 'enemigos': [{'bando': 'avaros', 'reino': 'Los emisarios del kagan'}, {'bando': 'eslavos', 'reino': 'La tribu del río'}, {'bando': 'eslavos', 'reino': 'La tribu del monte'}], 'voz': 'Borislav', 'historia': 'Siete tribus se reúnen entre las cuatro torres para decidir si van contigo o con el oro de los ávaros. Los emisarios del kagan, sus mensajeros, ya están allí repartiendo regalos, y algunas tribus se han puesto de su lado. Que vean de qué lado está la fuerza.', 'meta': 'Acaba con los emisarios del kagan y las tribus que están con ellos: quítales sus pueblos y derrota a todos sus soldados. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Los emisarios del kagan y dos tribus, que de momento van juntos', 'consejo': 'No todas las tribus quieren pelear contigo. Aguanta sin perder tus pueblos y verás.', 'avisos': {'tribu': 'La tribu del río ha visto cómo peleas y decide unirse a ti. Ahora está de tu lado.'}, 'en': {'nombre': 'The seven tribes', 'voz': 'Borislav', 'historia': "Seven tribes are meeting among the four towers to decide whether to go with you or with the Avars' gold. The khagan's emissaries, his messengers, are already there handing out gifts, and some tribes have taken their side. Let them see which side is strong.", 'meta': "Beat the khagan's emissaries and the tribes who are with them: take their villages and defeat all their soldiers. You have {t} turns. If they run out first, whoever has more points wins.", 'contra': "The khagan's emissaries and two tribes, who fight together for now", 'consejo': "Not every tribe wants to fight you. Hold on without losing your villages and you'll see.", 'avisos': {'tribu': "The river tribe has seen how you fight and decides to join you. Now it's on your side."}}}, {'id': 8, 'nombre': 'Fuera del bosque', 'mapa': 'llanura_avara', 'rivales': 3, 'batalla': 'campo', 'ejercito': {'yo': 18, 'rival': 4}, 'equipos': [0, 1, 1, 1], 'dificultad': 'dificil', 'limite': 15, 'enemigos': [{'bando': 'avaros', 'reino': 'Los jinetes del kagan'}, {'bando': 'avaros', 'reino': 'Los arqueros del kagan'}, {'bando': 'avaros', 'reino': 'Los jinetes de la llanura'}], 'voz': 'Borislav', 'historia': 'Ya somos muchos, Vesna, de todas las tribus. Pero mientras sigamos escondidos entre los árboles, el kagan seguirá mandando en la llanura. Hay que salir. Sus caballos son rápidos, pero nuestras lanzas son largas.', 'meta': 'Aquí no hay pueblos: solo tu ejército contra el suyo. Derrota a todos sus soldados. Tienes {t} turnos. Si se acaban antes, gana quien tenga más puntos.', 'contra': 'Tres grupos de soldados del kagan, que van juntos', 'consejo': 'Pon lanceros delante: los caballos no quieren chocar contra las lanzas.', 'en': {'nombre': 'Out of the forest', 'voz': 'Borislav', 'historia': 'There are many of us now, Vesna, from every tribe. But as long as we stay hidden among the trees, the khagan will keep ruling the plain. We have to come out. Their horses are fast, but our spears are long.', 'meta': 'There are no villages here: only your army against theirs. Defeat all their soldiers. You have {t} turns. If they run out first, whoever has more points wins.', 'contra': "Three groups of the khagan's soldiers, who fight together", 'consejo': "Put spearmen in front: horses don't like charging into spears.", 'avisos': {'avaros': "Another of the khagan's riders arrives from the plain!"}}, 'guion': [{'id': 'mas_avaros', 'cuando': {'turno': 10}, 'hacer': {'refuerzos': {'equipo': 1, 'tropas': ['caballero'], 'donde': 'borde'}, 'aviso': 'avaros'}}], 'avisos': {'avaros': '¡Llega otro jinete del kagan desde la llanura!'}}, {'id': 9, 'nombre': 'El Anillo', 'mapa': 'estepa', 'rivales': 2, 'batalla': 'asalto', 'ejercito': 18, 'equipos': [0, 1, 1], 'dificultad': 'dificil', 'limite': 26, 'guion': [{'id': 'maquinas_anillo', 'cuando': {'turno': 4}, 'hacer': {'refuerzos': {'jugador': 0, 'tropas': ['catapulta', 'catapulta'], 'donde': 'borde'}, 'aviso': 'catapultas'}}, {'id': 'vuelve_kagan', 'cuando': {'turno': 20}, 'hacer': {'refuerzos': {'equipo': 1, 'tropas': ['caballero', 'caballero', 'caballero'], 'donde': 'borde'}, 'aviso': 'kagan'}}], 'enemigos': [{'bando': 'avaros', 'reino': 'La guardia del Anillo', 'capital': 'El Anillo'}, {'bando': 'avaros', 'reino': 'Los jinetes que quedan'}], 'voz': 'La abuela Mokosha', 'historia': 'Los ávaros guardan todo lo que han robado en su gran campamento redondo, el Anillo, rodeado de vallas de madera. El kagan ha salido con su ejército y lo ha dejado con pocos guardias. No volverá a haber una ocasión así, niña. Pero date prisa: el kagan no tardará en volver.', 'meta': 'Aquí no tienes pueblo: solo tu ejército. Conquista el Anillo, el pueblo principal de su guardia. Tienes {t} turnos. Si se acaban y no lo has conquistado, pierdes.', 'contra': 'La guardia del Anillo y los jinetes que quedan, que van juntos', 'consejo': 'Date prisa: cuanto más tardes, más fácil es que vuelva el kagan con su ejército.', 'avisos': {'kagan': '¡El kagan vuelve antes de tiempo con sus jinetes!', 'catapultas': 'Radim llega con dos catapultas para romper las vallas del Anillo.'}, 'en': {'nombre': 'The Ring', 'voz': 'Grandmother Mokosha', 'historia': "The Avars keep everything they've stolen in their great round camp, the Ring, surrounded by wooden fences. The khagan has gone out with his army and left it with few guards. There'll never be a chance like this again, child. But hurry: the khagan won't be long.", 'meta': "You have no village here: only your army. Conquer the Ring, the main village of its guard. You have {t} turns. If they run out and you haven't conquered it, you lose.", 'contra': 'The guard of the Ring and the riders who stayed behind, who fight together', 'consejo': 'Hurry: the longer you take, the more likely the khagan comes back with his army.', 'avisos': {'kagan': 'The khagan is coming back early with his riders!', 'catapultas': 'Radim arrives with two catapults to break the fences of the Ring.'}}}, {'id': 10, 'nombre': 'La primavera', 'mapa': 'llanura_avara', 'rivales': 2, 'batalla': 'asalto', 'ejercito': 18, 'equipos': [0, 1, 1], 'dificultad': 'dificil', 'limite': 27, 'guion': [{'id': 'tribus_final', 'cuando': {'turno': 6}, 'hacer': {'refuerzos': {'tropas': ['espadachin', 'arquero', 'lancero', 'caballero'], 'donde': 'borde', 'jugador': 0}, 'aviso': 'tribus'}}, {'id': 'maquinas_final', 'cuando': {'turno': 9}, 'hacer': {'refuerzos': {'tropas': ['caballero', 'catapulta', 'catapulta'], 'donde': 'borde', 'jugador': 0}, 'aviso': 'maquinas'}}], 'enemigos': [{'bando': 'avaros', 'capital': 'El Gran Campamento'}, {'bando': 'avaros', 'reino': 'Los jinetes del kagan'}], 'voz': 'Bayan, el kagan de los ávaros', 'historia': '«Así que tú eres la bruja del bosque.» El kagan Bayan te mira desde su caballo, con todo su ejército detrás. «Mis abuelos cobraron tributo a los tuyos, y mis nietos se lo cobrarán a tus nietos. Aquí se acaba tu primavera.»', 'meta': 'Aquí no tienes pueblo: solo tu ejército. Conquista el pueblo principal del kagan Bayan. Tienes {t} turnos. Si se acaban y no lo has conquistado, pierdes.', 'contra': 'El kagan Bayan y sus jinetes, que van juntos', 'consejo': 'Es la última batalla. El kagan es muy fuerte: no le ataques con un soldado solo.', 'avisos': {'tribus': 'Llegan guerreros de todas las tribus: un espadachín, un arquero, un lancero y un caballero.', 'maquinas': 'Radim llega con un caballero y dos catapultas para romper la muralla del kagan.'}, 'en': {'nombre': 'Spring', 'voz': 'Bayan, khagan of the Avars', 'historia': '«So you are the witch of the forest.» Khagan Bayan looks at you from his horse, with his whole army behind him. «My grandfathers took tribute from yours, and my grandsons will take it from your grandsons. Your spring ends here.»', 'meta': "You have no village here: only your army. Conquer Khagan Bayan's main village. You have {t} turns. If they run out and you haven't conquered it, you lose.", 'contra': 'Khagan Bayan and his riders, who fight together', 'consejo': "This is the last battle. The khagan is very strong: don't attack him with just one soldier.", 'avisos': {'tribus': 'Warriors from every tribe arrive: a swordsman, an archer, a spearman and a knight.', 'maquinas': "Radim arrives with a knight and two catapults to break the khagan's wall."}}}]
